(()=>{
const attach=document.querySelector('.attach-btn'),picker=document.querySelector('.agent-picker'),toggle=document.getElementById('agent-toggle');
if(!attach||!picker||!toggle)return;
const host=document.createElement('div');host.className='composer-more';attach.before(host);host.append(attach);host.append(picker);
attach.removeAttribute('onclick');attach.setAttribute('aria-label','添加附件或智能体');attach.title='添加附件或智能体';attach.setAttribute('aria-expanded','false');attach.innerHTML='<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg>';
const menu=document.createElement('div');menu.className='composer-more-menu';menu.hidden=true;menu.setAttribute('role','menu');menu.innerHTML='<button type="button" role="menuitem" data-upload><svg viewBox="0 0 24 24"><path d="M21 11.5l-8.8 8.8a6 6 0 0 1-8.5-8.5l9.2-9.2a4 4 0 0 1 5.7 5.7l-9.2 9.2a2 2 0 0 1-2.8-2.8l8.5-8.5"/></svg>添加附件</button><button type="button" role="menuitem" data-agent><svg viewBox="0 0 24 24"><path d="m12 3 2.4 6.6L21 12l-6.6 2.4L12 21l-2.4-6.6L3 12l6.6-2.4Z"/></svg>智能体<span class="more-caret">›</span></button>';host.append(menu);
const selected=document.createElement('button');selected.type='button';selected.className='composer-agent-selected';selected.hidden=true;host.after(selected);
function close(){menu.hidden=true;attach.setAttribute('aria-expanded','false')}
attach.onclick=e=>{e.stopPropagation();const show=menu.hidden;closeAgentMenu();menu.hidden=!show;attach.setAttribute('aria-expanded',String(show))};
menu.querySelector('[data-upload]').onclick=e=>{e.stopPropagation();close();document.getElementById('ai-files').click()};
const openAgents=()=>{if(document.getElementById('agent-menu').hidden)toggleAgentMenu()};menu.querySelector('[data-agent]').onclick=e=>{e.stopPropagation();openAgents()};menu.querySelector('[data-agent]').onmouseenter=openAgents;menu.querySelector('[data-agent]').onfocus=openAgents;selected.onclick=e=>{e.stopPropagation();close();toggleAgentMenu()};host.addEventListener('click',e=>{if(e.target.closest('[data-direct],[data-skill-index]'))close()});
new MutationObserver(()=>{const name=toggle.dataset.selectedAgent?toggle.textContent.replace(/^[✧\s]+/,'').replace(/⌄$/,'').trim():'';selected.hidden=!name;selected.textContent='✧ '+name;selected.title=name}).observe(toggle,{childList:true,subtree:true,attributes:true,attributeFilter:['data-selected-agent','data-selected-skill']});
document.addEventListener('click',e=>{if(!host.contains(e.target))close()});document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});
const style=document.createElement('style');style.textContent='.composer-more{position:relative;display:flex;align-items:center;flex:none}.composer-more .agent-picker{position:static}body[data-system-theme] .reference-composer .composer-more .agent-picker #agent-toggle{display:none!important}.composer-more-menu{position:absolute;left:0;bottom:44px;width:176px;padding:6px;background:#fff;border:1px solid #e2e6ed;border-radius:10px;box-shadow:0 8px 28px #1919191a;z-index:100}.composer-more-menu[hidden]{display:none}.composer-more-menu button{display:flex;align-items:center;gap:10px;width:100%;height:38px;padding:0 10px;border:0;border-radius:7px;background:white;color:#111;font-size:14px;text-align:left;cursor:pointer}.composer-more-menu button:hover{background:#f2f6fc}.composer-more-menu button span{width:20px;text-align:center;color:#0067d1;font-size:18px}.composer-more .agent-menu{left:184px;bottom:44px;top:auto}@media(max-width:800px){.composer-more .agent-menu{left:0;bottom:134px}}.composer-agent-selected{height:32px;padding:4px 12px;max-width:330px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;border:1px solid #dce7f5;border-radius:18px;background:#eef5ff;color:#0067d1;font:inherit;cursor:pointer}.composer-agent-selected[hidden]{display:none}';style.textContent+='.reference-composer .composer-more .attach-btn{width:34px!important;height:34px!important;padding:0!important;border:0!important;border-radius:50%!important;background:#edf5ff!important;color:#191919!important;display:grid;place-items:center}.composer-more-menu button svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}.composer-more-menu .more-caret{margin-left:auto;color:#667085}';document.head.append(style);
})();
